@Test
public void testVariable() {
    for (int maxOrder = 1; maxOrder < 5; ++maxOrder) {
        checkF0F1(new DerivativeStructure(3, maxOrder, 0, 1.0), 1.0, 1.0, 0.0, 0.0);
