@Test
public void testHypotNoOverflow() {
    SparseGradient sgX = SparseGradient.createVariable(0, +3.0e250);
    SparseGradient sgY = SparseGradient.createVariable(1, -4.0e250);
    SparseGradient hypot = SparseGradient.hypot(sgX, sgY);
    Assert.assertEquals(5.0e250, hypot.getValue(), 1.0e235);
    Assert.assertEquals(sgX.getValue() / hypot.getValue(), hypot.getDerivative(0), 1.0e-10);
    Assert.assertEquals(sgY.getValue() / hypot.getValue(), hypot.getDerivative(1), 1.0e-10);
    SparseGradient sqrt = sgX.multiply(sgX).add(sgY.multiply(sgY)).sqrt();
    Assert.assertTrue(Double.isInfinite(sqrt.getValue()));
}

@Test
public void testHypotNeglectible() {
    SparseGradient sgSmall = SparseGradient.createVariable(0, +3.0e-10);
    SparseGradient sgLarge = SparseGradient.createVariable(1, -4.0e25);
    Assert.assertEquals(sgLarge.abs().getValue(), SparseGradient.hypot(sgSmall, sgLarge).getValue(), 1.0e-10);
    Assert.assertEquals(0, SparseGradient.hypot(sgSmall, sgLarge).getDerivative(0), 1.0e-10);
    Assert.assertEquals(-1, SparseGradient.hypot(sgSmall, sgLarge).getDerivative(1), 1.0e-10);
    Assert.assertEquals(sgLarge.abs().getValue(), SparseGradient.hypot(sgLarge, sgSmall).getValue(), 1.0e-10);
    Assert.assertEquals(0, SparseGradient.hypot(sgLarge, sgSmall).getDerivative(0), 1.0e-10);
    Assert.assertEquals(-1, SparseGradient.hypot(sgLarge, sgSmall).getDerivative(1), 1.0e-10);
}

@Test
public void testHypotSpecial() {
    Assert.assertTrue(Double.isNaN(SparseGradient.hypot(SparseGradient.createVariable(0, Double.NaN), SparseGradient.createVariable(0, +3.0e250)).getValue()));
    Assert.assertTrue(Double.isNaN(SparseGradient.hypot(SparseGradient.createVariable(0, +3.0e250), SparseGradient.createVariable(0, Double.NaN)).getValue()));
    Assert.assertTrue(Double.isInfinite(SparseGradient.hypot(SparseGradient.createVariable(0, Double.POSITIVE_INFINITY), SparseGradient.createVariable(0, +3.0e250)).getValue()));
    Assert.assertTrue(Double.isInfinite(SparseGradient.hypot(SparseGradient.createVariable(0, +3.0e250), SparseGradient.createVariable(0, Double.POSITIVE_INFINITY)).getValue()));
}

@Test
