        // Expected.
    }
    // X values not sorted.
    try {
        double[] xval = { 0.0, 1.0, 0.5 };
        double[] yval = { 0.0, 1.0, 2.0 };
        i.interpolate(xval, yval);
        Assert.fail("Failed to detect unsorted arguments.");
