public void testFitnessCaching() {
    // initialize a new genetic algorithm
    GeneticAlgorithm ga = new GeneticAlgorithm(new OnePointCrossover<Integer>(), // all selected chromosomes will be recombined (=crosssover)
    CROSSOVER_RATE, new BinaryMutation(), // no mutation
    MUTATION_RATE, new TournamentSelection(TOURNAMENT_ARITY));
    // initial population
    Population initial = randomPopulation();
    // stopping conditions
    StoppingCondition stopCond = new FixedGenerationCount(NUM_GENERATIONS);
    // run the algorithm
    ga.evolve(initial, stopCond);
    int neededCalls = POPULATION_SIZE + /*initial population*/
    (NUM_GENERATIONS - 1) * /*for each population*/
