    List<String> permutedData = Arrays.asList(new String[] { "d", "b", "c", "a", "d" });
    DummyRandomKey drk = new DummyRandomKey(RandomKey.inducedPermutation(origData, permutedData));
    List<String> decoded = drk.decode(origData);
