/**
 * test examples in user guide
 */
@Test
public void testExamples() {
    // Create a real matrix with two rows and three columns
    Dfp[][] matrixData = { { Dfp25.of(1), Dfp25.of(2), Dfp25.of(3) }, { Dfp25.of(2), Dfp25.of(5), Dfp25.of(3) } };
    FieldMatrix<Dfp> m = new BlockFieldMatrix<>(matrixData);
    // One more with three rows, two columns
    Dfp[][] matrixData2 = { { Dfp25.of(1), Dfp25.of(2) }, { Dfp25.of(2), Dfp25.of(5) }, { Dfp25.of(1), Dfp25.of(7) } };
    FieldMatrix<Dfp> n = new BlockFieldMatrix<>(matrixData2);
    // Now multiply m by n
    FieldMatrix<Dfp> p = m.multiply(n);
    Assert.assertEquals(2, p.getRowDimension());
    Assert.assertEquals(2, p.getColumnDimension());
    // Invert p
    FieldMatrix<Dfp> pInverse = new FieldLUDecomposition<>(p).getSolver().getInverse();
    Assert.assertEquals(2, pInverse.getRowDimension());
    Assert.assertEquals(2, pInverse.getColumnDimension());
    // Solve example
    Dfp[][] coefficientsData = { { Dfp25.of(2), Dfp25.of(3), Dfp25.of(-2) }, { Dfp25.of(-1), Dfp25.of(7), Dfp25.of(6) }, { Dfp25.of(4), Dfp25.of(-3), Dfp25.of(-5) } };
    FieldMatrix<Dfp> coefficients = new BlockFieldMatrix<>(coefficientsData);
    Dfp[] constants = { Dfp25.of(1), Dfp25.of(-2), Dfp25.of(1) };
    Dfp[] solution;
    solution = new FieldLUDecomposition<>(coefficients).getSolver().solve(new ArrayFieldVector<>(constants, false)).toArray();
    Assert.assertEquals(Dfp25.of(2).multiply(solution[0]).add(Dfp25.of(3).multiply(solution[1])).subtract(Dfp25.of(2).multiply(solution[2])).toDouble(), constants[0].toDouble(), 0d);
    Assert.assertEquals(Dfp25.of(-1).multiply(solution[0]).add(Dfp25.of(7).multiply(solution[1])).add(Dfp25.of(6).multiply(solution[2])).toDouble(), constants[1].toDouble(), 0d);
    Assert.assertEquals(Dfp25.of(4).multiply(solution[0]).subtract(Dfp25.of(3).multiply(solution[1])).subtract(Dfp25.of(5).multiply(solution[2])).toDouble(), constants[2].toDouble(), 0d);
}

