    FieldMatrix<Dfp> uRef = new Array2DRowFieldMatrix<>(Dfp25.getField(), new Dfp[][] { { Dfp25.of(1), Dfp25.of(2), Dfp25.of(3) }, { Dfp25.of(0), Dfp25.of(1), Dfp25.of(-3) }, { Dfp25.of(0), Dfp25.of(0), Dfp25.of(-1) } });
