/**
 * test solve
 */
@Test
public void testSolve() {
    FieldDecompositionSolver<Dfp> solver;
    solver = new FieldLUDecomposition<>(createDfpMatrix(testData)).getSolver();
    FieldMatrix<Dfp> b = createDfpMatrix(new int[][] { { 1, 0 }, { 2, -5 }, { 3, 1 } });
    FieldMatrix<Dfp> xRef = createDfpMatrix(new int[][] { { 19, -71 }, { -6, 22 }, { -2, 9 } });
    // using FieldMatrix
    FieldMatrix<Dfp> x = solver.solve(b);
    for (int i = 0; i < x.getRowDimension(); i++) {
        for (int j = 0; j < x.getColumnDimension(); j++) {
            Assert.assertEquals("(" + i + ", " + j + ")", xRef.getEntry(i, j), x.getEntry(i, j));
        }
    }
    // using ArrayFieldVector
    for (int j = 0; j < b.getColumnDimension(); j++) {
        final FieldVector<Dfp> xj = solver.solve(b.getColumnVector(j));
        for (int i = 0; i < xj.getDimension(); i++) {
            Assert.assertEquals("(" + i + ", " + j + ")", xRef.getEntry(i, j), xj.getEntry(i));
        }
    }
    // using SparseFieldVector
    for (int j = 0; j < b.getColumnDimension(); j++) {
        final SparseFieldVector<Dfp> bj;
        bj = new SparseFieldVector<>(Dfp25.getField(), b.getColumn(j));
        final FieldVector<Dfp> xj = solver.solve(bj);
        for (int i = 0; i < xj.getDimension(); i++) {
            Assert.assertEquals("(" + i + ", " + j + ")", xRef.getEntry(i, j), xj.getEntry(i));
        }
    }
}

