            Assert.assertEquals(expectedStart, actualStart);
            Assert.assertEquals(expectedEnd, actualEnd);
            expectedIndex = expectedStart;
        }

        @Override
        public double end() {
            return 0.0;
        }
    };
    v.walkInDefaultOrder(visitor, expectedStart, expectedEnd);
}

