        efode.setTime(0);
        efode.setPrimaryState(z);
        jacob.registerVariationalEquations(efode);
        integ.setMaxEvaluations(5000);
        integ.integrate(efode, 20.0);
        jacob.getCurrentMainSetJacobian(dZdZ0);
