@Test
public void testMissedEndEvent() throws DimensionMismatchException, NumberIsTooSmallException, MaxCountExceededException, NoBracketingException {
    final double t0 = 1878250320.0000029;
    final double tEvent = 1878250379.9999986;
    final double[] k = { 1.0e-4, 1.0e-5, 1.0e-6 };
    FirstOrderDifferentialEquations ode = new FirstOrderDifferentialEquations() {

        @Override
        public int getDimension() {
            return k.length;
        }

        @Override
        public void computeDerivatives(double t, double[] y, double[] yDot) {
            for (int i = 0; i < y.length; ++i) {
                yDot[i] = k[i] * y[i];
            }
        }
    };
    DormandPrince853Integrator integrator = new DormandPrince853Integrator(0.0, 100.0, 1.0e-10, 1.0e-10);
    double[] y0 = new double[k.length];
    for (int i = 0; i < y0.length; ++i) {
        y0[i] = i + 1;
    }
    double[] y = new double[k.length];
    integrator.setInitialStepSize(60.0);
    double finalT = integrator.integrate(ode, t0, y0, tEvent, y);
    Assert.assertEquals(tEvent, finalT, 5.0e-6);
    for (int i = 0; i < y.length; ++i) {
        Assert.assertEquals(y0[i] * JdkMath.exp(k[i] * (finalT - t0)), y[i], 1.0e-9);
    }
    integrator.setInitialStepSize(60.0);
    integrator.addEventHandler(new EventHandler() {

        @Override
        public void init(double t0, double[] y0, double t) {
        }

        @Override
        public void resetState(double t, double[] y) {
        }

        @Override
        public double g(double t, double[] y) {
            return t - tEvent;
        }

        @Override
        public Action eventOccurred(double t, double[] y, boolean increasing) {
            Assert.assertEquals(tEvent, t, 5.0e-6);
            return Action.CONTINUE;
        }
    }, Double.POSITIVE_INFINITY, 1.0e-20, 100);
    finalT = integrator.integrate(ode, t0, y0, tEvent + 120, y);
    Assert.assertEquals(tEvent + 120, finalT, 5.0e-6);
    for (int i = 0; i < y.length; ++i) {
        Assert.assertEquals(y0[i] * JdkMath.exp(k[i] * (finalT - t0)), y[i], 1.0e-9);
    }
}

