@Test
public void testIncreasingTolerance() throws DimensionMismatchException, NumberIsTooSmallException, MaxCountExceededException, NoBracketingException {
    int previousCalls = Integer.MAX_VALUE;
    AdaptiveStepsizeIntegrator integ = new DormandPrince853Integrator(0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
    for (int i = -12; i < -2; ++i) {
        TestProblem1 pb = new TestProblem1();
        double minStep = 0;
        double maxStep = pb.getFinalTime() - pb.getInitialTime();
        double scalAbsoluteTolerance = JdkMath.pow(10.0, i);
        double scalRelativeTolerance = 0.01 * scalAbsoluteTolerance;
        integ.setStepSizeControl(minStep, maxStep, scalAbsoluteTolerance, scalRelativeTolerance);
        TestProblemHandler handler = new TestProblemHandler(pb, integ);
        integ.addStepHandler(handler);
        integ.integrate(pb, pb.getInitialTime(), pb.getInitialState(), pb.getFinalTime(), new double[pb.getDimension()]);
        // the 1.3 factor is only valid for this test
        // and has been obtained from trial and error
        // there is no general relation between local and global errors
        Assert.assertTrue(handler.getMaximalValueError() < (1.3 * scalAbsoluteTolerance));
        Assert.assertEquals(0, handler.getMaximalTimeError(), 1.0e-12);
        int calls = pb.getCalls();
        Assert.assertEquals(integ.getEvaluations(), calls);
        Assert.assertTrue(calls <= previousCalls);
        previousCalls = calls;
    }
}

