@Test
public void testDecreasingSteps() throws DimensionMismatchException, NumberIsTooSmallException, MaxCountExceededException, NoBracketingException {
    for (TestProblemAbstract pb : new TestProblemAbstract[] { new TestProblem1(), new TestProblem2(), new TestProblem3(), new TestProblem4(), new TestProblem5(), new TestProblem6() }) {
        double previousValueError = Double.NaN;
        double previousTimeError = Double.NaN;
        for (int i = 4; i < 10; ++i) {
            double step = (pb.getFinalTime() - pb.getInitialTime()) * JdkMath.pow(2.0, -i);
            FirstOrderIntegrator integ = new LutherIntegrator(step);
            TestProblemHandler handler = new TestProblemHandler(pb, integ);
            integ.addStepHandler(handler);
            EventHandler[] functions = pb.getEventsHandlers();
            for (int l = 0; l < functions.length; ++l) {
                integ.addEventHandler(functions[l], Double.POSITIVE_INFINITY, 1.0e-6 * step, 1000);
            }
            Assert.assertEquals(functions.length, integ.getEventHandlers().size());
            double stopTime = integ.integrate(pb, pb.getInitialTime(), pb.getInitialState(), pb.getFinalTime(), new double[pb.getDimension()]);
            if (functions.length == 0) {
                Assert.assertEquals(pb.getFinalTime(), stopTime, 1.0e-10);
            }
            double error = handler.getMaximalValueError();
            if (i > 4) {
                Assert.assertTrue(error < 1.01 * JdkMath.abs(previousValueError));
            }
            previousValueError = error;
            double timeError = handler.getMaximalTimeError();
            if (i > 4) {
                Assert.assertTrue(timeError <= JdkMath.abs(previousTimeError));
            }
            previousTimeError = timeError;
            integ.clearEventHandlers();
            Assert.assertEquals(0, integ.getEventHandlers().size());
        }
    }
}

