@Test
public void testFitAccuracyDependsOnBoundary() {
    final CMAESOptimizer optimizer = new CMAESOptimizer(30000, 0, true, 10, 0, RandomSource.MT_64.create(), false, null);
    final MultivariateFunction fitnessFunction = new MultivariateFunction() {

        @Override
        public double value(double[] parameters) {
            final double target = 11.1;
            final double error = target - parameters[0];
            return error * error;
        }
    };
    final double[] start = { 1 };
    // No bounds.
    PointValuePair result = optimizer.optimize(new MaxEval(100000), new ObjectiveFunction(fitnessFunction), GoalType.MINIMIZE, SimpleBounds.unbounded(1), new PopulationSize(5), new Sigma(new double[] { 1e-1 }), new InitialGuess(start));
    final double resNoBound = result.getPoint()[0];
    // Optimum is near the lower bound.
    final double[] lower = { -20 };
    final double[] upper = { 5e16 };
    final double[] sigma = { 10 };
    result = optimizer.optimize(new MaxEval(100000), new ObjectiveFunction(fitnessFunction), GoalType.MINIMIZE, new PopulationSize(5), new Sigma(sigma), new InitialGuess(start), new SimpleBounds(lower, upper));
    final double resNearLo = result.getPoint()[0];
    // Optimum is near the upper bound.
    lower[0] = -5e16;
    upper[0] = 20;
    result = optimizer.optimize(new MaxEval(100000), new ObjectiveFunction(fitnessFunction), GoalType.MINIMIZE, new PopulationSize(5), new Sigma(sigma), new InitialGuess(start), new SimpleBounds(lower, upper));
    final double resNearHi = result.getPoint()[0];
    // System.out.println("resNoBound=" + resNoBound +
    //                    " resNearLo=" + resNearLo +
    //                    " resNearHi=" + resNearHi);
    // The two values currently differ by a substantial amount, indicating that
    // the bounds definition can prevent reaching the optimum.
    Assert.assertEquals(resNoBound, resNearLo, 1e-3);
    Assert.assertEquals(resNoBound, resNearHi, 1e-3);
}

