@Test
public void testMath226() {
    final double[] mean = { 1, 1, 10, 1 };
    final double[][] cov = { { 1, 3, 2, 6 }, { 3, 13, 16, 2 }, { 2, 16, 38, -1 }, { 6, 2, -1, 197 } };
    final RealMatrix covRM = MatrixUtils.createRealMatrix(cov);
    final Supplier<double[]> sg = new CorrelatedVectorFactory(mean, covRM, 1e-5).gaussian(RandomSource.WELL_1024_A.create());
    final double[] min = new double[mean.length];
    Arrays.fill(min, Double.POSITIVE_INFINITY);
