    Assert.assertEquals(2, testDa.getCapacity());
    testDa.addElement(1d);
    testDa.addElement(1d);
    Assert.assertEquals(2, testDa.getCapacity());
    testDa.addElement(1d);
    Assert.assertEquals(4, testDa.getCapacity());
}

