@Test
public void testOneSampleTTest() {
    double[] oneSidedP = { 2d, 0d, 6d, 6d, 3d, 3d, 2d, 3d, -6d, 6d, 6d, 6d, 3d, 0d, 1d, 1d, 0d, 2d, 3d, 3d };
    SummaryStatistics oneSidedPStats = new SummaryStatistics();
    for (int i = 0; i < oneSidedP.length; i++) {
        oneSidedPStats.addValue(oneSidedP[i]);
    }
    // Target comparison values computed using R version 1.8.1 (Linux version)
    Assert.assertEquals("one sample t stat", 3.86485535541, InferenceTestUtils.t(0d, oneSidedP), 10E-10);
    Assert.assertEquals("one sample t stat", 3.86485535541, InferenceTestUtils.t(0d, oneSidedPStats), 1E-10);
    Assert.assertEquals("one sample p value", 0.000521637019637, InferenceTestUtils.tTest(0d, oneSidedP) / 2d, 10E-10);
