@Test
public void testNextAfter() {
    test(new DfpDec(field, 1).nextAfter(pinf), new DfpDec(field, "1.0000000000000001"), 0, "NextAfter #1");
    test(new DfpDec(field, "1.0000000000000001").nextAfter(ninf), new DfpDec(field, 1), 0, "NextAfter #1.5");
    test(new DfpDec(field, 1).nextAfter(ninf), new DfpDec(field, "0.99999999999999999"), 0, "NextAfter #2");
    test(new DfpDec(field, "0.99999999999999999").nextAfter(new DfpDec(field, 2)), new DfpDec(field, 1), 0, "NextAfter #3");
    test(new DfpDec(field, -1).nextAfter(ninf), new DfpDec(field, "-1.0000000000000001"), 0, "NextAfter #4");
    test(new DfpDec(field, -1).nextAfter(pinf), new DfpDec(field, "-0.99999999999999999"), 0, "NextAfter #5");
    test(new DfpDec(field, "-0.99999999999999999").nextAfter(new DfpDec(field, -2)), new DfpDec(field, (byte) -1), 0, "NextAfter #6");
    test(new DfpDec(field, (byte) 2).nextAfter(new DfpDec(field, 2)), new DfpDec(field, 2L), 0, "NextAfter #7");
    test(new DfpDec(field, 0).nextAfter(new DfpDec(field, 0)), new DfpDec(field, 0), 0, "NextAfter #8");
    test(new DfpDec(field, -2).nextAfter(new DfpDec(field, -2)), new DfpDec(field, -2), 0, "NextAfter #9");
    test(new DfpDec(field, 0).nextAfter(new DfpDec(field, 1)), new DfpDec(field, "1e-131092"), DfpField.FLAG_UNDERFLOW, "NextAfter #10");
    test(new DfpDec(field, 0).nextAfter(new DfpDec(field, -1)), new DfpDec(field, "-1e-131092"), DfpField.FLAG_UNDERFLOW, "NextAfter #11");
    test(new DfpDec(field, "-1e-131092").nextAfter(pinf), new DfpDec(field, "-0"), DfpField.FLAG_UNDERFLOW | DfpField.FLAG_INEXACT, "Next After #12");
    test(new DfpDec(field, "1e-131092").nextAfter(ninf), new DfpDec(field, "0"), DfpField.FLAG_UNDERFLOW | DfpField.FLAG_INEXACT, "Next After #13");
    test(new DfpDec(field, "9.9999999999999999e131078").nextAfter(pinf), pinf, DfpField.FLAG_OVERFLOW | DfpField.FLAG_INEXACT, "Next After #14");
}

@Test
public void testPow() {
    // Test special cases exponent of zero
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("0")), factory.newDfp("1"), 0, "pow #1");
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("-0")), factory.newDfp("1"), 0, "pow #2");
    test(DfpMath.pow(factory.newDfp("2"), factory.newDfp("0")), factory.newDfp("1"), 0, "pow #3");
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("-0")), factory.newDfp("1"), 0, "pow #4");
    test(DfpMath.pow(pinf, factory.newDfp("-0")), factory.newDfp("1"), 0, "pow #5");
    test(DfpMath.pow(pinf, factory.newDfp("0")), factory.newDfp("1"), 0, "pow #6");
    test(DfpMath.pow(ninf, factory.newDfp("-0")), factory.newDfp("1"), 0, "pow #7");
    test(DfpMath.pow(ninf, factory.newDfp("0")), factory.newDfp("1"), 0, "pow #8");
    test(DfpMath.pow(qnan, factory.newDfp("0")), factory.newDfp("1"), 0, "pow #8");
    // exponent of one
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("1")), factory.newDfp("0"), 0, "pow #9");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("1")), factory.newDfp("-0"), 0, "pow #10");
    test(DfpMath.pow(factory.newDfp("2"), factory.newDfp("1")), factory.newDfp("2"), 0, "pow #11");
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("1")), factory.newDfp("-2"), 0, "pow #12");
    test(DfpMath.pow(pinf, factory.newDfp("1")), pinf, 0, "pow #13");
    test(DfpMath.pow(ninf, factory.newDfp("1")), ninf, 0, "pow #14");
    test(DfpMath.pow(qnan, factory.newDfp("1")), qnan, DfpField.FLAG_INVALID, "pow #14.1");
    // exponent of NaN
    test(DfpMath.pow(factory.newDfp("0"), qnan), qnan, DfpField.FLAG_INVALID, "pow #15");
    test(DfpMath.pow(factory.newDfp("-0"), qnan), qnan, DfpField.FLAG_INVALID, "pow #16");
    test(DfpMath.pow(factory.newDfp("2"), qnan), qnan, DfpField.FLAG_INVALID, "pow #17");
    test(DfpMath.pow(factory.newDfp("-2"), qnan), qnan, DfpField.FLAG_INVALID, "pow #18");
    test(DfpMath.pow(pinf, qnan), qnan, DfpField.FLAG_INVALID, "pow #19");
    test(DfpMath.pow(ninf, qnan), qnan, DfpField.FLAG_INVALID, "pow #20");
    test(DfpMath.pow(qnan, qnan), qnan, DfpField.FLAG_INVALID, "pow #21");
    // radix of NaN
    test(DfpMath.pow(qnan, factory.newDfp("1")), qnan, DfpField.FLAG_INVALID, "pow #22");
    test(DfpMath.pow(qnan, factory.newDfp("-1")), qnan, DfpField.FLAG_INVALID, "pow #23");
    test(DfpMath.pow(qnan, pinf), qnan, DfpField.FLAG_INVALID, "pow #24");
    test(DfpMath.pow(qnan, ninf), qnan, DfpField.FLAG_INVALID, "pow #25");
    test(DfpMath.pow(qnan, qnan), qnan, DfpField.FLAG_INVALID, "pow #26");
    // (x > 1) ^ pinf = pinf,    (x < -1) ^ pinf = pinf
    test(DfpMath.pow(factory.newDfp("2"), pinf), pinf, 0, "pow #27");
    test(DfpMath.pow(factory.newDfp("-2"), pinf), pinf, 0, "pow #28");
    test(DfpMath.pow(pinf, pinf), pinf, 0, "pow #29");
    test(DfpMath.pow(ninf, pinf), pinf, 0, "pow #30");
    // (x > 1) ^ ninf = +0,    (x < -1) ^ ninf = +0
    test(DfpMath.pow(factory.newDfp("2"), ninf), factory.getZero(), 0, "pow #31");
    test(DfpMath.pow(factory.newDfp("-2"), ninf), factory.getZero(), 0, "pow #32");
    test(DfpMath.pow(pinf, ninf), factory.getZero(), 0, "pow #33");
    test(DfpMath.pow(ninf, ninf), factory.getZero(), 0, "pow #34");
    // (-1 < x < 1) ^ pinf = 0
    test(DfpMath.pow(factory.newDfp("0.5"), pinf), factory.getZero(), 0, "pow #35");
    test(DfpMath.pow(factory.newDfp("-0.5"), pinf), factory.getZero(), 0, "pow #36");
    // (-1 < x < 1) ^ ninf = pinf
    test(DfpMath.pow(factory.newDfp("0.5"), ninf), pinf, 0, "pow #37");
    test(DfpMath.pow(factory.newDfp("-0.5"), ninf), pinf, 0, "pow #38");
    // +/- 1  ^ +/-inf  = NaN
    test(DfpMath.pow(factory.getOne(), pinf), qnan, DfpField.FLAG_INVALID, "pow #39");
    test(DfpMath.pow(factory.getOne(), ninf), qnan, DfpField.FLAG_INVALID, "pow #40");
    test(DfpMath.pow(factory.newDfp("-1"), pinf), qnan, DfpField.FLAG_INVALID, "pow #41");
    test(DfpMath.pow(factory.getOne().negate(), ninf), qnan, DfpField.FLAG_INVALID, "pow #42");
    // +0  ^ +anything except 0, NAN  = +0
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("1")), factory.newDfp("0"), 0, "pow #43");
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("1e30")), factory.newDfp("0"), 0, "pow #44");
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("1e-30")), factory.newDfp("0"), 0, "pow #45");
    test(DfpMath.pow(factory.newDfp("0"), pinf), factory.newDfp("0"), 0, "pow #46");
    // -0  ^ +anything except 0, NAN, odd integer  = +0
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("2")), factory.newDfp("0"), 0, "pow #47");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("1e30")), factory.newDfp("0"), 0, "pow #48");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("1e-30")), factory.newDfp("0"), DfpField.FLAG_INEXACT, "pow #49");
    test(DfpMath.pow(factory.newDfp("-0"), pinf), factory.newDfp("0"), 0, "pow #50");
    // +0  ^ -anything except 0, NAN  = +INF
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("-1")), pinf, 0, "pow #51");
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("-1e30")), pinf, 0, "pow #52");
    test(DfpMath.pow(factory.newDfp("0"), factory.newDfp("-1e-30")), pinf, 0, "pow #53");
    test(DfpMath.pow(factory.newDfp("0"), ninf), pinf, 0, "pow #54");
    // -0  ^ -anything except 0, NAN, odd integer  = +INF
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("-2")), pinf, 0, "pow #55");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("-1e30")), pinf, 0, "pow #56");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("-1e-30")), pinf, DfpField.FLAG_INEXACT, "pow #57");
    test(DfpMath.pow(factory.newDfp("-0"), ninf), pinf, 0, "pow #58");
    // -0  ^ -odd integer   =  -INF
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("-1")), ninf, DfpField.FLAG_INEXACT, "pow #59");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("-12345")), ninf, DfpField.FLAG_INEXACT, "pow #60");
    // -0  ^ +odd integer   =  -0
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("3")), factory.newDfp("-0"), DfpField.FLAG_INEXACT, "pow #61");
    test(DfpMath.pow(factory.newDfp("-0"), factory.newDfp("12345")), factory.newDfp("-0"), DfpField.FLAG_INEXACT, "pow #62");
    // pinf  ^ +anything   = pinf
    test(DfpMath.pow(pinf, factory.newDfp("3")), pinf, 0, "pow #63");
    test(DfpMath.pow(pinf, factory.newDfp("1e30")), pinf, 0, "pow #64");
    test(DfpMath.pow(pinf, factory.newDfp("1e-30")), pinf, 0, "pow #65");
    test(DfpMath.pow(pinf, pinf), pinf, 0, "pow #66");
    // pinf  ^ -anything   = +0
    test(DfpMath.pow(pinf, factory.newDfp("-3")), factory.getZero(), 0, "pow #67");
    test(DfpMath.pow(pinf, factory.newDfp("-1e30")), factory.getZero(), 0, "pow #68");
    test(DfpMath.pow(pinf, factory.newDfp("-1e-30")), factory.getZero(), 0, "pow #69");
    test(DfpMath.pow(pinf, ninf), factory.getZero(), 0, "pow #70");
    // ninf  ^ anything   = -0 ^ -anything
    // ninf  ^ -anything except 0, NAN, odd integer  = +0
    test(DfpMath.pow(ninf, factory.newDfp("-2")), factory.newDfp("0"), 0, "pow #71");
    test(DfpMath.pow(ninf, factory.newDfp("-1e30")), factory.newDfp("0"), 0, "pow #72");
    test(DfpMath.pow(ninf, factory.newDfp("-1e-30")), factory.newDfp("0"), DfpField.FLAG_INEXACT, "pow #73");
    test(DfpMath.pow(ninf, ninf), factory.newDfp("0"), 0, "pow #74");
    // ninf  ^ +anything except 0, NAN, odd integer  = +INF
    test(DfpMath.pow(ninf, factory.newDfp("2")), pinf, 0, "pow #75");
    test(DfpMath.pow(ninf, factory.newDfp("1e30")), pinf, 0, "pow #76");
    test(DfpMath.pow(ninf, factory.newDfp("1e-30")), pinf, DfpField.FLAG_INEXACT, "pow #77");
    test(DfpMath.pow(ninf, pinf), pinf, 0, "pow #78");
    // ninf  ^ +odd integer   =  -INF
    test(DfpMath.pow(ninf, factory.newDfp("3")), ninf, DfpField.FLAG_INEXACT, "pow #79");
    test(DfpMath.pow(ninf, factory.newDfp("12345")), ninf, DfpField.FLAG_INEXACT, "pow #80");
    // ninf  ^ -odd integer   =  -0
    test(DfpMath.pow(ninf, factory.newDfp("-3")), factory.newDfp("-0"), DfpField.FLAG_INEXACT, "pow #81");
    test(DfpMath.pow(ninf, factory.newDfp("-12345")), factory.newDfp("-0"), DfpField.FLAG_INEXACT, "pow #82");
    // -anything ^ integer
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("3")), factory.newDfp("-8"), DfpField.FLAG_INEXACT, "pow #83");
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("16")), factory.newDfp("65536"), 0, "pow #84");
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("-3")), factory.newDfp("-0.125"), DfpField.FLAG_INEXACT, "pow #85");
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("-4")), factory.newDfp("0.0625"), 0, "pow #86");
    // -anything ^ noninteger = NaN
    test(DfpMath.pow(factory.newDfp("-2"), factory.newDfp("-4.1")), qnan, DfpField.FLAG_INVALID | DfpField.FLAG_INEXACT, "pow #87");
    // Some fractional cases.
    test(DfpMath.pow(factory.newDfp("2"), factory.newDfp("1.5")), factory.newDfp("2.8284271247461901"), DfpField.FLAG_INEXACT, "pow #88");
}

