@Test
public void testIncrementTooManyTimes() {
    final int start = 0;
    final int max = 3;
    final int step = 1;
    for (int i = 1; i <= max + 4; i++) {
        final IntegerSequence.Incrementor inc = IntegerSequence.Incrementor.create().withStart(start).withMaximalCount(max).withIncrement(step);
        Assert.assertTrue(inc.canIncrement(max - 1));
        Assert.assertFalse(inc.canIncrement(max));
        try {
            inc.increment(i);
        } catch (MaxCountExceededException e) {
            if (i < max) {
                Assert.fail("i=" + i);
            }
            // Otherwise, the exception is expected.
        }
    }
}

