    double[][] pairs = { { -50.0, 50.0 }, { Double.POSITIVE_INFINITY, 1.0 }, { Double.NEGATIVE_INFINITY, 1.0 }, { Double.NaN, 1.0 }, { Double.POSITIVE_INFINITY, 0.0 }, { Double.NEGATIVE_INFINITY, 0.0 }, { Double.NaN, 0.0 }, { Double.NaN, Double.NEGATIVE_INFINITY }, { Double.NaN, Double.POSITIVE_INFINITY }, { Precision.SAFE_MIN, Precision.EPSILON } };
    for (double[] pair : pairs) {
        assertEquals("min(" + pair[0] + ", " + pair[1] + ")", Math.min(pair[0], pair[1]), AccurateMath.min(pair[0], pair[1]), Precision.EPSILON);
        assertEquals("min(" + pair[1] + ", " + pair[0] + ")", Math.min(pair[1], pair[0]), AccurateMath.min(pair[1], pair[0]), Precision.EPSILON);
        assertEquals("max(" + pair[0] + ", " + pair[1] + ")", Math.max(pair[0], pair[1]), AccurateMath.max(pair[0], pair[1]), Precision.EPSILON);
        assertEquals("max(" + pair[1] + ", " + pair[0] + ")", Math.max(pair[1], pair[0]), AccurateMath.max(pair[1], pair[0]), Precision.EPSILON);
    }
}

