@Test
public void testCheckOrder() {
    MathArrays.checkOrder(new double[] { -15, -5.5, -1, 2, 15 }, MathArrays.OrderDirection.INCREASING, true);
    MathArrays.checkOrder(new double[] { -15, -5.5, -1, 2, 2 }, MathArrays.OrderDirection.INCREASING, false);
    MathArrays.checkOrder(new double[] { 3, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, true);
    MathArrays.checkOrder(new double[] { 3, 0, 0, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, false);
    try {
        MathArrays.checkOrder(new double[] { -15, -5.5, -1, -1, 2, 15 }, MathArrays.OrderDirection.INCREASING, true);
        Assert.fail("an exception should have been thrown");
    } catch (NonMonotonicSequenceException e) {
        // Expected
    }
    try {
        MathArrays.checkOrder(new double[] { -15, -5.5, -1, -2, 2 }, MathArrays.OrderDirection.INCREASING, false);
        Assert.fail("an exception should have been thrown");
    } catch (NonMonotonicSequenceException e) {
        // Expected
    }
    try {
        MathArrays.checkOrder(new double[] { 3, 3, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, true);
        Assert.fail("an exception should have been thrown");
    } catch (NonMonotonicSequenceException e) {
        // Expected
    }
    try {
        MathArrays.checkOrder(new double[] { 3, -1, 0, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, false);
        Assert.fail("an exception should have been thrown");
    } catch (NonMonotonicSequenceException e) {
        // Expected
    }
    try {
        MathArrays.checkOrder(new double[] { 3, 0, -5.5, -11, -10 }, MathArrays.OrderDirection.DECREASING, false);
        Assert.fail("an exception should have been thrown");
    } catch (NonMonotonicSequenceException e) {
        // Expected
    }
}

@Test
public void testIsMonotonic() {
    Assert.assertFalse(MathArrays.isMonotonic(new double[] { -15, -5.5, -1, -1, 2, 15 }, MathArrays.OrderDirection.INCREASING, true));
    Assert.assertTrue(MathArrays.isMonotonic(new double[] { -15, -5.5, -1, 0, 2, 15 }, MathArrays.OrderDirection.INCREASING, true));
    Assert.assertFalse(MathArrays.isMonotonic(new double[] { -15, -5.5, -1, -2, 2 }, MathArrays.OrderDirection.INCREASING, false));
    Assert.assertTrue(MathArrays.isMonotonic(new double[] { -15, -5.5, -1, -1, 2 }, MathArrays.OrderDirection.INCREASING, false));
    Assert.assertFalse(MathArrays.isMonotonic(new double[] { 3, 3, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, true));
    Assert.assertTrue(MathArrays.isMonotonic(new double[] { 3, 2, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, true));
    Assert.assertFalse(MathArrays.isMonotonic(new double[] { 3, -1, 0, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, false));
    Assert.assertTrue(MathArrays.isMonotonic(new double[] { 3, 0, 0, -5.5, -11, -27.5 }, MathArrays.OrderDirection.DECREASING, false));
}

@Test
public void testIsMonotonicComparable() {
    Assert.assertFalse(MathArrays.isMonotonic(new Double[] { Double.valueOf(-15), Double.valueOf(-5.5), Double.valueOf(-1), Double.valueOf(-1), Double.valueOf(2), Double.valueOf(15) }, MathArrays.OrderDirection.INCREASING, true));
    Assert.assertTrue(MathArrays.isMonotonic(new Double[] { Double.valueOf(-15), Double.valueOf(-5.5), Double.valueOf(-1), Double.valueOf(0), Double.valueOf(2), Double.valueOf(15) }, MathArrays.OrderDirection.INCREASING, true));
    Assert.assertFalse(MathArrays.isMonotonic(new Double[] { Double.valueOf(-15), Double.valueOf(-5.5), Double.valueOf(-1), Double.valueOf(-2), Double.valueOf(2) }, MathArrays.OrderDirection.INCREASING, false));
    Assert.assertTrue(MathArrays.isMonotonic(new Double[] { Double.valueOf(-15), Double.valueOf(-5.5), Double.valueOf(-1), Double.valueOf(-1), Double.valueOf(2) }, MathArrays.OrderDirection.INCREASING, false));
    Assert.assertFalse(MathArrays.isMonotonic(new Double[] { Double.valueOf(3), Double.valueOf(3), Double.valueOf(-5.5), Double.valueOf(-11), Double.valueOf(-27.5) }, MathArrays.OrderDirection.DECREASING, true));
    Assert.assertTrue(MathArrays.isMonotonic(new Double[] { Double.valueOf(3), Double.valueOf(2), Double.valueOf(-5.5), Double.valueOf(-11), Double.valueOf(-27.5) }, MathArrays.OrderDirection.DECREASING, true));
    Assert.assertFalse(MathArrays.isMonotonic(new Double[] { Double.valueOf(3), Double.valueOf(-1), Double.valueOf(0), Double.valueOf(-5.5), Double.valueOf(-11), Double.valueOf(-27.5) }, MathArrays.OrderDirection.DECREASING, false));
    Assert.assertTrue(MathArrays.isMonotonic(new Double[] { Double.valueOf(3), Double.valueOf(0), Double.valueOf(0), Double.valueOf(-5.5), Double.valueOf(-11), Double.valueOf(-27.5) }, MathArrays.OrderDirection.DECREASING, false));
}

