@Test
public void testVerifyValuesNegative() {
    final double[] nullArray = null;
    Assert.assertFalse(MathArrays.verifyValues(singletonArray, 0, 0));
    Assert.assertFalse(MathArrays.verifyValues(testArray, 0, 0));
    Assert.assertTrue(MathArrays.verifyValues(testArray, 0, 0, true));
    Assert.assertFalse(MathArrays.verifyValues(testArray, testWeightsArray, 0, 0));
    Assert.assertTrue(MathArrays.verifyValues(testArray, testWeightsArray, 0, 0, true));
    try {
        // start past end
        MathArrays.verifyValues(singletonArray, 2, 1);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
    try {
        // end past end
        MathArrays.verifyValues(testArray, 0, 7);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
    try {
        // start negative
        MathArrays.verifyValues(testArray, -1, 1);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
    try {
        // length negative
        MathArrays.verifyValues(testArray, 0, -1);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
    try {
        // null array
        MathArrays.verifyValues(nullArray, 0, 1);
        Assert.fail("Expecting NullArgumentException");
    } catch (NullArgumentException ex) {
        // expected
    }
    try {
        // null weights array
        MathArrays.verifyValues(testArray, nullArray, 0, 1);
        Assert.fail("Expecting NullArgumentException");
    } catch (NullArgumentException ex) {
        // expected
    }
    try {
        // weights.length != value.length
        MathArrays.verifyValues(singletonArray, testWeightsArray, 0, 1);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
    try {
        // can't have negative weights
        MathArrays.verifyValues(testArray, testNegativeWeightsArray, 0, 6);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
    try {
        // can't have all zero weights
        MathArrays.verifyValues(testArray, new double[testArray.length], 0, 6);
        Assert.fail("Expecting MathIllegalArgumentException");
    } catch (MathIllegalArgumentException ex) {
        // expected
    }
}

