    max = Math.PI;
    result = transformer.apply(f, min, max, size);
    Assert.assertEquals(-(size >> 1), result[2], tolerance);
    for (int i = 0; i < size; i += i == 1 ? 2 : 1) {
        Assert.assertEquals(0.0, result[i], tolerance);
    }
}

